"""Question-specific explanations for module 2, including its exam."""
# Key suffix -> correct rationale, explanations for distractors in letter order.
FEEDBACK = {
'l01-c01': ('FROM задаёт источник строк.', ['Столбцы результата задаёт SELECT.','Сортировку задаёт ORDER BY.','Структуру меняют DDL-команды, например ALTER TABLE.']),
'l01-c02': ('Без ORDER BY порядок не гарантируется.', ['Первичный ключ не задаёт порядок чтения.','Физический порядок вставки не является обещанием SQL.','Имя таблицы не задаёт сортировку строк.']),
'l01-q01': ('SELECT возвращает названия товаров, не меняя таблицу.', ['Проекция результата не удаляет столбцы таблицы.','Для изменения данных нужен UPDATE.','Создание таблицы выполняет CREATE TABLE.']),
'l01-q02': ('Имя табличного источника следует за FROM.', ['После SELECT задают выражения результата, а не источник.','WHERE содержит условие отбора, а не объявление источника.','ORDER BY задаёт ключ сортировки, а не источник.']),
'l01-q03': ('SELECT получает результат из источника.', ['Неподходящие строки исключаются из результата, а не удаляются из таблицы.','Без ORDER BY сортировка не гарантируется.','Число строк зависит от источника и условий, а не от самого слова SELECT.']),
'l01-q04': ('Для гарантированного порядка нужен ORDER BY.', ['Числовой ID не заставляет СУБД читать строки по возрастанию.','Порядок вставки не гарантируется результатом SELECT.','SELECT не удаляет строки.']),
'l01-q05': ('Сначала SELECT со списком столбцов, затем FROM с таблицей.', ['Таблица и столбцы поменяны ролями.','FROM не ставят перед SELECT в этой форме запроса.','AND соединяет логические условия; список столбцов разделяется запятой.']),
'l02-c01': ('Звёздочка раскрывает столбцы указанного источника.', ['Источник products не означает все таблицы базы.','Звёздочка не ограничивает проекцию первичным ключом.','Звёздочка не является предикатом IS NOT NULL.']),
'l02-c02': ('AS задаёт имя выражения в результате.', ['Постоянный столбец создаёт ALTER TABLE, а не AS.','Псевдоним не выполняет UPDATE цены.','Фильтрация требует WHERE; имя результата не фильтрует строки.']),
'l02-q01': ('В SELECT явно названы product_name и price.', ['Без звёздочки остальные столбцы не добавляются автоматически.','Проекция не отбрасывает NULL-цены сама по себе.','Ограничение до первой строки не указано.']),
'l02-q02': ('Уменьшение на 10% означает умножение на 0.9.', ['Вычитание 10 — абсолютная скидка, не 10 процентов.','UPDATE нельзя вставить в список выражений SELECT.','Равенство сравнивает с 0.9, а не вычисляет новую цену.']),
'l02-q03': ('Псевдоним меняет имя результата, а не исходную схему.', ['Постоянное переименование не происходит.','У отдельной строки нет собственного имени столбца: схема общая.','AS не удаляет исходный столбец.']),
'l02-q04': ('SELECT * выбирает все столбцы одного источника products.', ['Звёздочка не расширяет FROM на всю базу.','Числовой тип не является условием раскрытия звёздочки.','Первичный ключ не исключается из звёздочки.']),
'l02-q05': ('Стоимость позиции = количество × цена единицы.', ['Сложение количества и цены не даёт стоимость позиции.','Равенство даёт логический результат, не стоимость.','Деление количества на цену имеет другой смысл.']),
'l03-c01': ('Нужен строгий отбор price > 3000.', ['Меньше — противоположное направление сравнения.','Равенство оставляет только границу.','Не равно включает и цены ниже 3000.']),
'l03-c02': ('Строковый литерал PostgreSQL записывают в одинарных кавычках.', ['Без кавычек paid разбирается как имя.','Двойные кавычки обозначают идентификатор, не строковый литерал.','Квадратные скобки не являются строковыми кавычками PostgreSQL.']),
'l03-q01': ('>= включает граничное значение 3000.', ['WHERE в SELECT не меняет цену.','Отбор из результата не удаляет строки из таблицы.','Для сортировки нужен ORDER BY.']),
'l03-q02': ('Стандарт SQL использует <> для неравенства; PostgreSQL также понимает !=.', ['!= работает в PostgreSQL, но вопрос спрашивает стандартное написание SQL.','=> не является стандартным оператором неравенства.','>< не является оператором неравенства.']),
'l03-q03': ('Статус — столбец, paid — строковое значение.', ['Незакавыченное paid будет именем, а не нужной строкой.','В кавычки заключён status, а paid осталось именем: роли перепутаны.','IS не принимает произвольную строку как замену равенства.']),
'l03-q04': ('WHERE может обращаться к доступному столбцу, не включённому в SELECT.', ['Отбор и состав результирующих столбцов независимы.','Участие в PK не требуется для фильтра.','Звёздочка не нужна для обращения к столбцу в WHERE.']),
'l03-q05': ('<> исключает цену 3000; строки с NULL также не проходят WHERE.', ['Равенство 3000 — противоположный отбор.','Неравенство включает также цены ниже границы.','Неравенство включает также цены выше границы.']),
'l04-c01': ('AND требует истинности обоих условий.', ['OR допускает истинность одного условия.','NOT отрицает одно условие.','LIKE сопоставляет строковый шаблон.']),
'l04-c02': ('AND имеет более высокий приоритет, чем OR.', ['OR имеет более низкий приоритет.','Приоритеты AND и OR различны.','Имя столбца не меняет грамматику операторов.']),
'l04-q01': ('Оба требования должны выполняться: нужная категория и цена.', ['OR допускает товар другой категории, если цена подходит.','NOT категории исключает нужную категорию и не проверяет цену.','AND OR подряд без операнда — неверное выражение.']),
'l04-q02': ('AND связывает new с customer_id до применения внешнего OR.', ['Эти скобки ограничили бы customer_id также и оплаченные заказы.','В исходнике есть OR: его нельзя произвольно заменить AND.','В исходнике есть AND: его нельзя произвольно заменить OR.']),
'l04-q03': ('Скобки объединяют два статуса, затем ограничивают покупателя.', ['Без скобок оплаченные заказы других покупателей тоже пройдут.','Один статус не может одновременно быть paid и new.','Отрицание группы выбирает другие статусы и не проверяет покупателя.']),
'l04-q04': ('NOT отрицает условие о cancelled.', ['Равенство cancelled без отрицания даёт противоположную группу.','NOT не является сортировкой.','Логическое отрицание не удаляет записи.']),
'l04-q05': ('AND истинен, когда истинны оба операнда.', ['Хотя бы одного TRUE достаточно для OR, а не AND.','FALSE AND FALSE даёт FALSE.','Значения обоих операндов существенны.']),
'l05-c01': ('BETWEEN включает нижнюю и верхнюю границы.', ['Строгие > и < не эквивалентны BETWEEN.','Верхняя граница тоже включена.','Нижняя граница тоже включена.']),
'l05-c02': ('% в LIKE означает ноль или более любых символов.', ['Один символ обозначает подчёркивание.','% не ограничивается цифрами.','Пробел — обычный символ, а не смысл %.']),
'l05-q01': ('BETWEEN эквивалентен >= нижняя и <= верхняя.', ['Строгие сравнения потеряют обе границы.','Два равенства оставят только края, потеряв внутренние значения.','Одновременно <=3000 и >=5000 для обычного числа невозможно.']),
'l05-q02': ('IN проверяет совпадение хотя бы с одним элементом списка.', ['Один статус не обязан равняться двум разным строкам одновременно.','Отсутствие в списке проверяет NOT IN.','Поиск подстроки задают шаблоном, не списком равенств.']),
'l05-q03': ('Для окончания строки нужен % перед суффиксом.', ['% после слова проверяет начало, а не окончание.','Подчёркивания требуют ровно по одному символу с обеих сторон.','Без % это точное совпадение всего слова.']),
'l05-q04': ('Товар% допускает продолжение после префикса Товар.', ['% допускает не ровно один, а любое число символов.','Для окончания нужен % перед словом.','Шаблон допускает непустое продолжение, не только точное совпадение.']),
'l05-q05': ('NULL в наборе может сделать NOT IN равным UNKNOWN.', ['NOT IN — предикат, он не удаляет таблицу.','IN и NOT IN применимы и к строковым значениям.','Строковые наборы поддерживаются; проблема именно в NULL и трёхзначной логике.']),
'l06-c01': ('Для отсутствующей даты используется IS NULL.', ['= NULL даёт UNKNOWN, а не проверку отсутствия.','== не является оператором равенства PostgreSQL для этого выражения.','<> NULL тоже даёт UNKNOWN.']),
'l06-c02': ('NULL = NULL даёт UNKNOWN.', ['Два неизвестных значения нельзя объявить равными обычным =.','Неизвестность не означает доказанное неравенство.','Результат сравнения не числовой ноль.']),
'l06-q01': ('NULL означает отсутствующее или неизвестное значение.', ['Ноль — известное число.','Пустая строка — известная строка длины ноль.','Текст NULL в кавычках — обычная строка, не маркер отсутствия.']),
'l06-q02': ('Сравнение с NULL даёт UNKNOWN, WHERE сохраняет только TRUE.', ['NULL допускается в SQL и имеет специальные проверки.','WHERE поддерживает столбцы дат.','Знак равенства сравнивает, а не удаляет значение.']),
'l06-q03': ('WHERE сохраняет только TRUE.', ['UNKNOWN не проходит фильтр.','Ни FALSE, ни UNKNOWN не проходят фильтр.','Строки с неистинным предикатом отбрасываются из результата.']),
'l06-q04': ('NOT UNKNOWN остаётся UNKNOWN.', ['Отрицание неизвестности не доказывает истинность.','Отрицание неизвестности не доказывает ложность.','Логическая оценка не превращается в текстовую строку NULL.']),
'l06-q05': ('Чтобы сохранить отсутствующую дату, добавляют IS NULL через OR.', ['AND требует и известного сравнения, и отсутствия значения, поэтому нужные строки не пройдут.','= NULL не даёт TRUE и не заменяет IS NULL.','NOT не включает UNKNOWN: оно остаётся UNKNOWN.']),
'l07-c01': ('DESC задаёт убывание.', ['ASC задаёт возрастание.','SORT DOWN не является синтаксисом ORDER BY PostgreSQL.','WHERE фильтрует; DESC не превращает его в сортировку.']),
'l07-c02': ('Второй ключ разрешает равенство первого.', ['Первый ключ остаётся главным.','Дополнительный ключ не исключает строки.','Сортировка результата не меняет ID.']),
'l07-q01': ('ORDER BY задаёт порядок строк результата.', ['Отбор строк выполняет WHERE.','Постоянные столбцы не создаются сортировкой.','Связи таблиц не объявляются в ORDER BY.']),
'l07-q02': ('Для непустых дат DESC даёт порядок от новых к старым.', ['От старых к новым — ASC.','Сортировка сама по себе не отбирает NULL.','Явный ключ сортировки не является случайным порядком.']),
'l07-q03': ('Сначала status ASC, при равенстве — created_at DESC.', ['Ключи нельзя читать справа налево.','Второй ключ действует при равных статусах.','created_at не заменяет основной status.']),
'l07-q04': ('Уникальный последний ключ разрешает оставшиеся ничьи.', ['Удаление даты меняет требуемый основной порядок.','WHERE не устанавливает порядок строк.','Изменение направления не разрешает равные даты.']),
'l07-q05': ('Положение NULL зависит от СУБД и параметров; в PostgreSQL ASC по умолчанию NULLS LAST, DESC — NULLS FIRST.', ['Единого положения для всех направлений и СУБД нет.','NULL не всегда первый: ASC в PostgreSQL по умолчанию ставит его последним.','NULL не всегда последний: DESC в PostgreSQL по умолчанию ставит его первым.']),
'l08-c01': ('DISTINCT относится ко всей выбранной комбинации.', ['Столбец b тоже участвует в сравнении строк результата.','DISTINCT не выбирает последнюю строку.','Исходная таблица не изменяется.']),
'l08-c02': ('LIMIT без ORDER BY не определяет конкретные первые строки.', ['LIMIT ограничивает выдачу, не удаляет данные.','LIMIT допустим в SELECT.','ORDER BY используется в SELECT для порядка выдачи.']),
'l08-q01': ('DISTINCT category_id оставляет уникальные значения в результате.', ['Исходные строки products не удаляются.','Возвращается не только первое, а каждое различное значение.','Удаление дублей не гарантирует сортировку.']),
'l08-q02': ('Дубликат определяется всей комбинацией category_id и price.', ['Одинаковая категория с разной ценой — разные строки результата.','Одинаковая цена при разных категориях — разные строки.','Не выбранный product_id не участвует в DISTINCT этой проекции.']),
'l08-q03': ('В PostgreSQL используется LIMIT 5.', ['SELECT FIRST 5 не эта форма синтаксиса PostgreSQL.','TOP — синтаксис SQL Server, не всех СУБД.','ROWS 5 без правильной конструкции FETCH не заменяет LIMIT.']),
'l08-q04': ('OFFSET 10 пропускает первые десять строк упорядоченного результата.', ['Количество возвращаемых строк задаёт LIMIT/FETCH, не OFFSET.','OFFSET не задаёт ключи сортировки.','Пропуск результата не удаляет исходные строки.']),
'l08-q05': ('SQL Server использует TOP 10; синтаксис ограничения зависит от диалекта.', ['LIMIT характерен для PostgreSQL, не для SQL Server.','Слова «во всех версиях» неверны: стандартная форма и поддержка зависят от диалекта и версии.','DISTINCT удаляет повторы, а не задаёт число строк.']),
}

# Exam: independently authored rules; per-choice explanations follow the same semantic concepts.
EXAM_RULES = [
 ('FROM задаёт источник, SELECT — столбцы, WHERE — отбор, ORDER BY — сортировку.', ['SELECT описывает проекцию.','WHERE описывает предикат.','ORDER BY описывает порядок.']),
 ('Звёздочка выбирает все столбцы названного источника.', ['Она не добавляет другие таблицы в FROM.','Она не ограничивается PK.','Она не ограничивает количество строк до одной.']),
 ('Выражение вычисляется и получает имя line_total только в результате.', ['SELECT не обновляет каталог.','Постоянный столбец не создаётся выражением.','Вычисление не является WHERE.']),
 ('Нужна цена строго ниже 2500: WHERE price < 2500.', ['> выбирает более дорогие строки.','= выбирает только границу.','ORDER BY сортирует результат сравнения, а не фильтрует строки.']),
 ('Строковый литерал в PostgreSQL — в одинарных кавычках.', ['Голое слово обозначает имя.','Квадратные скобки не обозначают строковый литерал.','Обратные кавычки не являются строковыми кавычками PostgreSQL.']),
 ('Оба условия должны выполняться, поэтому нужен AND.', ['OR пропускает также строки только с одним подходящим признаком.','Запятая не соединяет предикаты WHERE.','IN требует набор в скобках, не голую строку.']),
 ('OR истинен, если хотя бы один операнд TRUE.', ['Оба TRUE требуются для AND.','Два FALSE дают FALSE.','Второй операнд влияет на результат.']),
 ('Группу двух статусов нужно ограничить одним покупателем.', ['Без внешних скобок paid пройдёт для любого покупателя.','Один статус не равен paid и new одновременно.','Отрицание выбирает другие статусы и не задаёт покупателя.']),
 ('Включительный диапазон задаёт BETWEEN.', ['IN задаёт список, не диапазон.','LIKE задаёт текстовый шаблон.','DISTINCT устраняет дубли результата.']),
 ('BETWEEN 1000 AND 2000 включает обе границы и внутренние значения.', ['Строгие границы исключили бы края.','Не только края входят в диапазон.','BETWEEN не является исключением двух значений.']),
 ('IN сравнивает с каждым значением списка.', ['LIKE принимает шаблон, не такой список.','BETWEEN задаёт диапазон, не перечисление трёх статусов.','Строковые литералы сами по себе не логические операнды AND.']),
 ('Для подстроки book нужны проценты с двух сторон.', ['book% проверяет начало.','%book проверяет окончание.','_book_ требует ровно один символ с каждой стороны.']),
 ('Подчёркивание LIKE означает ровно один произвольный символ.', ['Ноль или больше обозначает %.','Символ не ограничивается цифрой.','Это не обозначение обязательного пробела.']),
 ('Отсутствие email проверяют IS NULL.', ['= NULL даёт UNKNOWN.','<> NULL тоже даёт UNKNOWN.','== не является таким оператором SQL PostgreSQL.']),
 ('Обычное сравнение с NULL даёт UNKNOWN.', ['TRUE не доказано неизвестным значением.','UNKNOWN не равнозначно FALSE.','Сравнение не возвращает число 10.']),
 ('WHERE пропускает только TRUE.', ['UNKNOWN не проходит.','FALSE и UNKNOWN отбрасываются.','FALSE не проходит.']),
 ('NOT UNKNOWN остаётся UNKNOWN, строка не проходит WHERE.', ['Неизвестность не превращается в TRUE.','NULL не заменяется нулём.','Такой предикат синтаксически допустим.']),
 ('ASC задаёт возрастание.', ['DESC задаёт убывание.','WHERE не задаёт сортировку.','В PostgreSQL используется ORDER BY, а не SORT BY.']),
 ('Первый ключ status главнее второго created_at.', ['created_at применяется при равных status.','Ключи имеют порядок, они не равноприоритетны.','Оба ключа участвуют в сортировке.']),
 ('Уникальный дополнительный ключ разрешает ничьи.', ['Без ORDER BY порядок не гарантируется.','SELECT * меняет проекцию, не разрешает ничьи.','DISTINCT не создаёт стабильного порядка.']),
 ('DISTINCT относится к паре category_id,price.', ['price тоже участвует в сравнении.','Исходные строки не удаляются.','DISTINCT не гарантирует сортировку.']),
 ('В PostgreSQL число строк ограничивает LIMIT.', ['TOP — другой диалект.','ROWCOUNT не эта конструкция PostgreSQL.','FIRST без FETCH не заменяет LIMIT.']),
 ('DESC выбирает более дорогие строки первыми, LIMIT оставляет три.', ['Самые дешёвые потребовали бы ASC.','Строки таблицы не удаляются.','Явная сортировка не является случайной.']),
 ('OFFSET пропускает строки результата.', ['Он не удаляет исходные строки.','Направление задают ASC/DESC.','Уникальность задаёт DISTINCT.']),
 ('Пагинации нужен устойчивый порядок с разрешением ничьих.', ['LIMIT остаётся ограничением результата.','DISTINCT не включается автоматически.','WHERE решает другую задачу — отбор.']),
]
for i, entry in enumerate(EXAM_RULES,1):
    FEEDBACK[f'exam-q{i:02}']=entry
